script="""let translations={};const lang=new URLSearchParams(location.search).get('lang')==='en'?'en':'ru';
function translatePublic(){if(lang!=='en'||location.pathname==='/panel')return;document.documentElement.lang='en';const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){if(['SCRIPT','STYLE'].includes(n.parentElement.tagName))continue;const key=n.textContent.trim();if(translations[key])n.textContent=n.textContent.replace(key,translations[key]);}for(const n of document.querySelectorAll('[placeholder]'))if(translations[n.placeholder])n.placeholder=translations[n.placeholder];for(const a of document.querySelectorAll('a[href^="/"]')){const u=new URL(a.href);u.searchParams.set('lang','en');a.href=u.pathname+u.search+u.hash;}}
"""
s=s.replace('(async()=>{try{',script+"(async()=>{try{translations=await (await fetch('/locales/'+lang+'.json')).json();")
s=s.replace('else landing()}catch(e)', 'else landing();translatePublic()}catch(e)')
p.write_text(s)
